import SwiftUI

struct AnimatedWeatherBackground: View {
  let kind: WeatherKind
  let isDay: Bool
  var body: some View {
    ZStack {
      LinearGradient(colors: colors, startPoint: .topLeading, endPoint: .bottomTrailing).ignoresSafeArea()
      TimelineView(.animation) { timeline in
        Canvas { context, size in draw(context: &context, size: size, time: timeline.date.timeIntervalSinceReferenceDate) }
      }.ignoresSafeArea().allowsHitTesting(false)
    }
  }
  private var colors: [Color] {
    switch kind {
    case .clear: return isDay ? [.blue,.cyan,.orange.opacity(0.8)] : [.black,Color.indigo.opacity(0.7)]
    case .cloudy,.fog: return [Color.gray.opacity(0.75),Color.blue.opacity(0.45)]
    case .drizzle,.rain: return [Color.black.opacity(0.85),Color.blue.opacity(0.5)]
    case .snow: return [Color.blue.opacity(0.5),Color.white.opacity(0.65)]
    case .storm: return [Color.black,Color.indigo.opacity(0.6)]
    }
  }
  private func draw(context: inout GraphicsContext, size: CGSize, time: TimeInterval) {
    let count = (kind == .rain || kind == .drizzle || kind == .storm) ? 40 : (kind == .snow ? 32 : 16)
    for i in 0..<count {
      let seed = Double((i * 137) % 997) / 997.0
      let x = (seed * size.width * 1.37).truncatingRemainder(dividingBy: size.width)
      if kind == .rain || kind == .drizzle || kind == .storm {
        let y = (time * (220 + Double(i % 7) * 25) + Double(i * 83)).truncatingRemainder(dividingBy: size.height + 80) - 40
        var p = Path(); p.move(to: .init(x:x,y:y)); p.addLine(to: .init(x:x-8,y:y+24))
        context.stroke(p, with: .color(.white.opacity(0.28)), lineWidth: 1.2)
      } else if kind == .snow {
        let y = (time * (36 + Double(i % 5) * 8) + Double(i * 57)).truncatingRemainder(dividingBy: size.height + 40) - 20
        let d = sin(time * 0.7 + Double(i)) * 18
        context.fill(Path(ellipseIn: .init(x:x+d,y:y,width:4,height:4)), with: .color(.white.opacity(0.6)))
      } else {
        let y = size.height * (0.15 + 0.045 * Double(i))
        context.fill(Path(ellipseIn: .init(x:x-35,y:y,width:90,height:22)), with: .color(.white.opacity(kind == .fog ? 0.06 : 0.035)))
      }
    }
  }
}
